import json

program_text = '''
def find_nonoverlap_rectangles(grid):
    h, w = len(grid), len(grid[0])
    all_eights = set((r, c) for r in range(h) for c in range(w) if grid[r][c] == 8)
    uncovered = all_eights.copy()
    rectangles = []

    while uncovered:
        r, c = min(uncovered, key=lambda x: (x[0], x[1]))
        max_r, max_c = r, c

        for col in range(c+1, w):
            if (r, col) not in all_eights:
                break
            found = True
            found_r = r
            for dr in range(1, h):
                if (r+dr, col) not in all_eights:
                    found = False
                    break
                found_r = r + dr
            cols_all = all((rr, col) in all_eights for rr in range(r, found_r+1))
            if cols_all:
                max_c = col
                max_r = found_r
            else:
                break
        rectangles.append((r, c, max_r, max_c))
        for dr in range(r, max_r+1):
            for dc in range(c, max_c+1):
                uncovered.discard((dr, dc))
    return rectangles

def transform(grid):
    h, w = len(grid), len(grid[0])
    rects = find_nonoverlap_rectangles(grid)
    result = [[grid[r][c] for c in range(w)] for r in range(h)]

    for idx, rect in enumerate(rects):
        r, c, rb, cb = rect
        if idx == 0:
            color = 2
        elif idx == 1:
            color = 1
        elif idx == 2:
            color = 3
        else:
            color = 4
        for rr in range(r, rb+1):
            for cc in range(c, cb+1):
                result[rr][cc] = color
    return result

